    op.execute(
        """
        UPDATE autoreplies.delivery AS d SET stage = last.stage
        FROM (
            SELECT DISTINCT ON (e.data->>'delivery_id')
                e.data->>'delivery_id' AS delivery_id,
                CASE e.kind
                    WHEN 'autoreply.matched' THEN 'sending'
                    WHEN 'autoreply.sent' THEN 'waiting_click'
                    WHEN 'autoreply.clicked' THEN 'clicked'
                    WHEN 'autoreply.follow_asked' THEN 'follow_asked'
                    WHEN 'autoreply.delivered' THEN 'delivered'
                    WHEN 'autoreply.send_failed' THEN CASE e.data->>'stage'
                        WHEN 'intro' THEN 'dm_failed'
                        WHEN 'material' THEN 'material_failed' END
                END AS stage
            FROM activity.event AS e
            WHERE e.data->>'delivery_id' IS NOT NULL
              AND (e.kind IN ('autoreply.matched', 'autoreply.sent', 'autoreply.clicked',
                              'autoreply.follow_asked', 'autoreply.delivered')
                   OR (e.kind = 'autoreply.send_failed'
                       AND e.data->>'stage' IN ('intro', 'material')))
            ORDER BY e.data->>'delivery_id', e.occurred_at DESC, e.id DESC
        ) AS last
        WHERE d.id::text = last.delivery_id AND d.delivered_at IS NULL
        """
    )
